// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount > 0);
        vm.assume(actor != address(0) && actor != address(this) && actor != address(c));
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool sent,) = address(c).call{value: amount}("");
        require(sent, "initial deposit failed");
        assertEq(c.balances(actor), amount);

        vm.prank(actor);
        c.withdraw();
        vm.deal(actor, amount);
        vm.prank(actor);
        address(c).call{value: amount}("");

        bool ok;
        vm.prank(actor);
        try c.withdraw() { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}
